// # Context-manager body: the with hoists the name first; the loop's binds are
// # reseats of that pointer local.
// def with_section() -> None:
//     with CM(4) as k:
//         for i in range(2):  # tpyc: ok
//             if i == 0:
//                 f = Flat(i)
//             else:
//                 f = Flat(i + k)
//         f.n += 1
//         print("with_body", f.n)
void with_section() {
    std::optional<Flat> __slot_1;
    std::optional<Flat> __slot_2;
    Flat* f;
    auto __ctx_1 = CM(4);
    auto k = __ctx_1.__enter__();
    try {
        for (int32_t i = 0; i < 2; ++i) {
            if ((i == 0)) {
                f = &*(__slot_1 = Flat(i));
            } else {
                f = &*(__slot_2 = Flat((::tpy::add_check<int32_t>(i, k))));
            }
        }
        f->n = ::tpy::add_check<int32_t>(f->n, 1);
        std::cout << "with_body" << " " << f->n << "\n";
        goto __with_exit_1;
    } catch (::tpy::BaseException& __exc_1) {
        __ctx_1.__exit__({}, &__exc_1, {});
        throw;
    } catch (...) {
        __ctx_1.__exit__({}, nullptr, {});
        throw;
    }
    __with_exit_1:
    __ctx_1.__exit__({}, nullptr, {});
}

