// # the CALLER's element, so the post-loop mutation is observed on `pics` -- a
// # frame-slot copy would leave it behind.
// def gen_sibling(pics: list[Pic]) -> Iterator[int32]:
//     for i in range(2):
//         p = pics[i]  # tpyc: ok
//         yield p.n                                     # -> S_RESUME_0
//     for k in range(2):
